<script setup>
import {ref,computed,onBeforeUnmount,watch} from 'vue'
import WorkspaceLayout from '../components/WorkspaceLayout.vue'
import {api,errorMessage} from '../workspace-api'
import {auth} from '../auth'
const summary=ref(null),events=ref([]),health=ref(null),error=ref(''),loading=ref(false),memo=ref(''),saved=ref(''),saving=ref(false)
const routerStatus=ref(null),routerCapability=ref(null)
const routerStateLabel=computed(()=>routerCapability.value?.enabled!==true?'默认关闭':routerStatus.value?.shadowOnly||routerCapability.value?.shadowOnly?'影子模式':'灰度已启用')
const routerTiers=[{key:'local',name:'Qwen3-4B'},{key:'flash',name:'DeepSeek Flash'},{key:'pro',name:'DeepSeek Pro'},{key:'abstain',name:'安全回退'}]
const tierTotal=computed(()=>routerTiers.reduce((sum,tier)=>sum+Math.max(0,Number(routerStatus.value?.tierCounts?.[tier.key])||0),0))
const tierPercent=key=>tierTotal.value?Math.max(0,Number(routerStatus.value?.tierCounts?.[key])||0)/tierTotal.value*100:0
// Old installations and fixtures omit router endpoints. Capabilities is the opt-in gate.
async function readRouter(){
 const {data:capabilities}=await api.get('/ai/capabilities')
 if(capabilities?.router?.enabled!==true)return {capability:capabilities?.router||null,status:null}
 const [result]=await Promise.allSettled([api.get('/ai/router/status')])
 return {capability:capabilities.router,status:result.status==='fulfilled'?result.value.data:null}
}
let epoch=0,closed=false
const labels={RUNNING:'运行中',SUCCEEDED:'成功',FAILED:'失败',CANCELLED:'取消',UNKNOWN:'结果未知'}
const number=value=>value==null?'未知':Number(value).toLocaleString('zh-CN')
async function refresh(){if(!auth.user?.id||saving.value)return;const token=++epoch;loading.value=true;error.value='';const owner=auth.user?.id
 try{const values=await Promise.allSettled([api.get('/ai/governance'),api.get('/ai/governance/events'),api.get('/ai/manus/memory'),auth.user?.role==='admin'?api.get('/ops/health'):Promise.resolve({data:null}),readRouter()]);if(closed||token!==epoch||owner!==auth.user?.id)return
 if(values[0].status==='fulfilled')summary.value=values[0].value.data
 if(values[1].status==='fulfilled')events.value=values[1].value.data||[]
 if(values[2].status==='fulfilled')memo.value=values[2].value.data?.text||''
 health.value=values[3].status==='fulfilled'?values[3].value.data:null
 routerCapability.value=values[4].status==='fulfilled'?values[4].value.capability:null
 routerStatus.value=values[4].status==='fulfilled'?values[4].value.status:null
 const failure=values.slice(0,4).find(value=>value.status==='rejected');if(failure)error.value=errorMessage(failure.reason)
 }catch(e){if(token===epoch)error.value=errorMessage(e)}finally{if(token===epoch)loading.value=false}}
async function save(nextText=memo.value){if(saving.value||loading.value||!auth.user?.id)return;const owner=auth.user?.id,token=epoch;saving.value=true;saved.value='';error.value='';try{await api.put('/ai/manus/memory',{text:nextText});if(!closed&&owner===auth.user?.id&&token===epoch){memo.value=nextText;saved.value='已保存；下一轮主对话将使用此便签。'}}catch(e){if(!closed&&owner===auth.user?.id&&token===epoch)error.value=errorMessage(e)}finally{if(token===epoch)saving.value=false}}
watch(()=>auth.user?.id,user=>{epoch++;summary.value=null;events.value=[];health.value=null;routerStatus.value=null;routerCapability.value=null;memo.value='';saved.value='';error.value='';loading.value=false;saving.value=false;if(user)refresh()},{immediate:true})
onBeforeUnmount(()=>{closed=true;epoch++})
</script>
<template><WorkspaceLayout title="用量与运行状态" description="查看当前账号的调用额度、已知用量和最近执行状态。">
<div class="row"><button @click="refresh" :disabled="loading||saving">{{loading?'读取中…':'刷新状态'}}</button><span v-if="summary" class="muted">日账期 {{summary.day}} · {{summary.timezone}}</span></div><p v-if="error" role="alert" class="error">{{error}}</p>
<template v-if="summary"><div class="metrics-grid"><section class="panel"><h2>今日模型调用</h2><strong>{{number(summary.requests)}} / {{number(summary?.limits?.dailyRequests)}}</strong><p>受治理的模型请求计数</p></section><section class="panel"><h2>Token 预算占用</h2><strong>{{number(summary.budgetChargedTokens)}} / {{number(summary?.limits?.dailyTokens)}}</strong><p>已知用量 {{number(summary.knownTokens)}}；未知用量调用 {{number(summary.unknownUsageRequests)}}</p></section><section class="panel"><h2>正在执行</h2><strong>{{number(summary.active)}} / {{number(summary?.limits?.accountConcurrency)}}</strong><p>费用未知：尚未配置供应商价格，不能把 Token 额度当作金额预算。</p></section></div>
<p class="notice" role="status" v-if="summary.remainingTokens===0||summary.requests>=summary?.limits?.dailyRequests">今日额度已用完，新模型请求会被拒绝。已发送的请求可能仍由供应商计费。</p><p class="notice" v-else-if="summary.failures">今日存在 {{summary.failures}} 条失败、取消或结果未知记录。请根据调用编号定位，避免重复发送结果未明的任务。</p>
<p class="muted">每次调用按预留估算与已知用量的较大值占用预算，未知用量保留预留额度；实际费用与 Token 以供应商账单为准。{{summary.scope}}</p>
<section class="panel"><h2>最近调用</h2><p v-if="!events.length">今日暂无记录。</p><div class="event-table"><table v-if="events.length"><thead><tr><th>状态</th><th>模型</th><th>输入 / 输出 Token</th><th>耗时</th><th>调用编号</th></tr></thead><tbody><tr v-for="item in events" :key="item.traceId"><td>{{labels[item.status]||item.status}}</td><td>{{item.provider}} / {{item.model}}</td><td>{{number(item.inputTokens)}} / {{number(item.outputTokens)}}</td><td>{{number(item.durationMs)}} ms</td><td><code>{{item.traceId}}</code><small v-if="item.requestId">请求 {{item.requestId}}</small></td></tr></tbody></table></div></section>
</template>
<section class="panel router-telemetry" data-testid="router-telemetry">
 <div class="telemetry-heading"><div><span class="telemetry-eyebrow">ROUTING INTELLIGENCE</span><h2>64M 智能路由引擎遥测</h2></div><span class="engine-status" :class="{enabled:routerCapability?.enabled===true}"><i></i>{{routerStateLabel}}</span></div>
 <template v-if="routerStatus">
  <div class="telemetry-circuit"><span class="circuit-dot" :class="{cooling:routerStatus.circuitOpen}"></span>熔断器：{{routerStatus.circuitOpen?'熔断冷却中':'健康'}}<span class="muted">{{routerStatus.circuitOpen?'已自动回退，冷却后恢复探测':'异常请求自动安全回退'}}</span></div>
  <div class="telemetry-metrics"><div><span>总路由决策数</span><strong>{{number(routerStatus.totalDecisions)}}</strong></div><div><span>实际命中数</span><strong>{{number(routerStatus.appliedCount)}}</strong></div><div><span>安全回退数</span><strong>{{number(routerStatus.fallbackCount)}}</strong></div><div><span>平均耗时</span><strong>{{routerStatus.avgLatencyMs==null?'未知':Number(routerStatus.avgLatencyMs).toFixed(1)}} <small>ms</small></strong></div></div>
  <div class="telemetry-distribution"><h3>档位命中分布</h3><div v-for="tier in routerTiers" :key="tier.key" class="telemetry-tier" :data-tier="tier.key"><div><span>{{tier.name}} <small>{{tier.key}}</small></span><span>{{number(routerStatus.tierCounts?.[tier.key]??0)}} <small>· {{tierPercent(tier.key).toFixed(1)}}%</small></span></div><div class="telemetry-track"><span :style="{width:tierPercent(tier.key)+'%'}"></span></div></div></div>
  <p class="muted telemetry-footnote">引擎累计观测 · {{routerStatus.shadowOnly?'影子模式仅观测，不改变实际执行模型。':'实际费用以供应商账单为准。'}}</p>
 </template>
 <p v-else class="muted telemetry-empty">{{loading?'正在读取引擎状态…':routerCapability?.enabled===true?'路由遥测暂不可用，对话仍可正常使用。':'智能路由默认关闭，当前对话继续使用所选模型。'}}</p>
</section>
<section class="panel memo"><h2>主对话参考便签</h2><p class="muted">由你明确保存、修改或清空；跨主对话使用。它不会授予工具权限，也不会自动替你执行任务。</p><textarea aria-label="主对话参考便签" v-model="memo" maxlength="4000" rows="6" placeholder="例如：回复使用中文；项目使用 Java 21；交付时列出实际执行的验证。"></textarea><div class="row"><button :disabled="saving||loading" @click="save()">{{saving?'保存中…':'保存便签'}}</button><button class="secondary" :disabled="saving||loading" @click="save('')">清空便签</button><span role="status">{{saved}}</span></div></section>
<section v-if="health" class="panel"><h2>管理员网关状态</h2><p class="muted">以下只证明网关与部署配置状态，不代表模型、工具或全部依赖健康。</p><pre data-testid="gateway-health">{{JSON.stringify(health,null,2)}}</pre></section>
</WorkspaceLayout></template>
<style scoped>
.metrics-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:20px 0}.panel{min-width:0;margin-bottom:20px;padding:24px;border:1px solid var(--yb-border);border-radius:16px;background:var(--yb-bg-surface);box-shadow:0 2px 8px #0f172a03}.panel h2{font-size:17px;margin:0 0 12px;color:var(--yb-ink);letter-spacing:-.025em}.panel strong{font-size:23px;font-variant-numeric:tabular-nums;color:var(--yb-ink)}.panel p{line-height:1.7;margin:10px 0}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.muted,small{color:var(--yb-ink-muted);font-size:13px}small{display:block;margin-top:5px}.notice{background:#fff4da;padding:16px;border-radius:12px;margin-bottom:16px}.error{color:#a92e2e}.event-table{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px;font-variant-numeric:tabular-nums}td,th{text-align:left;padding:12px;border-bottom:1px solid var(--yb-border);vertical-align:top}th{background:var(--yb-bg-subtle);color:var(--yb-ink-secondary);font-weight:600}tbody tr:hover{background:var(--yb-bg-canvas)}code{font-size:11px;font-family:var(--yb-font-mono)}textarea{width:100%;margin:12px 0;box-sizing:border-box;padding:13px 15px;border:1px solid var(--yb-border-strong);border-radius:12px;color:var(--yb-ink);background:var(--yb-bg-surface);transition:border-color var(--yb-motion),box-shadow var(--yb-motion);resize:vertical}textarea:focus{outline:none;border-color:var(--yb-accent);box-shadow:0 0 0 3px var(--yb-accent-ring)}button{border:1px solid transparent;border-radius:8px;background:var(--yb-accent);color:white;padding:10px 15px;cursor:pointer;transition:background var(--yb-motion),box-shadow var(--yb-motion)}button:hover:not(:disabled){background:var(--yb-accent-hover)}button.secondary{background:var(--yb-bg-surface);color:var(--yb-ink-secondary);border-color:var(--yb-border)}button.secondary:hover:not(:disabled){background:var(--yb-bg-hover)}button:focus-visible{outline:3px solid var(--yb-accent-ring);outline-offset:2px}button:disabled{opacity:.55;cursor:default}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.telemetry-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.telemetry-eyebrow{display:block;color:var(--yb-accent);font-size:10px;font-weight:650;letter-spacing:.12em;margin-bottom:8px}.telemetry-heading h2{margin-bottom:0}.engine-status{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--yb-border);border-radius:999px;padding:6px 10px;font-size:12px;color:var(--yb-ink-muted);background:var(--yb-bg-subtle)}.engine-status i,.circuit-dot{height:6px;width:6px;display:inline-block;border-radius:50%;background:#94a3b8}.engine-status.enabled{background:var(--yb-accent-soft);border-color:var(--yb-router-flash-border);color:var(--yb-accent)}.engine-status.enabled i{background:var(--yb-accent)}.telemetry-circuit{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:12px;margin:20px 0;color:var(--yb-ink-secondary)}.telemetry-circuit .muted{font-size:12px}.circuit-dot{background:#10b981}.circuit-dot.cooling{background:#94a3b8}.telemetry-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.telemetry-metrics>div{border:1px solid var(--yb-border);border-radius:12px;padding:16px;background:var(--yb-bg-canvas);min-width:0}.telemetry-metrics>div>span{display:block;color:var(--yb-ink-muted);font-size:12px;margin-bottom:10px}.telemetry-metrics strong{font-size:24px;overflow-wrap:anywhere}.telemetry-metrics small{display:inline;font-size:12px;font-weight:400}.telemetry-distribution{margin-top:24px}.telemetry-distribution h3{font-size:13px;color:var(--yb-ink);margin:0 0 14px}.telemetry-tier+.telemetry-tier{margin-top:14px}.telemetry-tier>div:first-child{display:flex;justify-content:space-between;gap:12px;font-size:12px;font-variant-numeric:tabular-nums;color:var(--yb-ink-secondary)}.telemetry-tier small{display:inline;font-size:11px;margin-left:4px}.telemetry-track{height:6px;border-radius:999px;background:var(--yb-bg-subtle);margin-top:7px;overflow:hidden}.telemetry-track>span{display:block;height:100%;border-radius:inherit;background:var(--yb-accent)}.telemetry-tier[data-tier="local"] .telemetry-track>span{background:#10b981}.telemetry-tier[data-tier="pro"] .telemetry-track>span{background:#8b5cf6}.telemetry-tier[data-tier="abstain"] .telemetry-track>span{background:#94a3b8}.panel .telemetry-footnote{margin:20px 0 0;font-size:12px}.panel .telemetry-empty{margin:18px 0 0;padding:16px;border-radius:12px;background:var(--yb-bg-canvas)}
@media(max-width:800px){.metrics-grid{grid-template-columns:1fr}.telemetry-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.panel{padding:18px}}@media(max-width:420px){.telemetry-metrics{gap:8px}.telemetry-metrics>div{padding:12px}.telemetry-metrics strong{font-size:21px}.telemetry-tier small{font-size:10px}.telemetry-tier>div:first-child{font-size:11px}}
</style>
